        const double ai = K2_20*P_ddh1_3_h2_1_i + K2_6*P_dh1_3_dh2_1_i + K2_16*P_dh1_3_dh2_2_i + K2_6*P_dh1_1_dh2_3_i + K2_6*P_dh1_2_dh2_3_i;
        const double br = 0.0;
