      { const double ar = K2_14*P_h1_3_h2_6_r + K2_16*P_h1_6_h2_6_r;
        const double ai = K2_14*P_h1_3_h2_6_i + K2_16*P_h1_6_h2_6_i;
        const double br = 0.0;
        const double bi = 0.0;
        gr += R_rm4_f2*(ar - bi); gi += R_rm4_f2*(ai + br); }
      { const double ar = K2_2*P_dh1_3_h2_6_r + K2_6*P_dh1_6_h2_6_r + K2_6*P_h1_6_dh2_6_r;
        const double ai = K2_2*P_dh1_3_h2_6_i + K2_6*P_dh1_6_h2_6_i + K2_6*P_h1_6_dh2_6_i;
        const double br = 0.0;
        const double bi = 0.0;
        gr += R_rm3_f2*(ar - bi); gi += R_rm3_f2*(ai + br); }
      { const double ar = K2_20*P_ddh1_6_h2_6_r + K2_16*P_dh1_6_dh2_6_r;
        const double ai = K2_20*P_ddh1_6_h2_6_i + K2_16*P_dh1_6_dh2_6_i;
        const double br = 0.0;
        const double bi = 0.0;
        gr += R_rm2_f2*(ar - bi); gi += R_rm2_f2*(ai + br); }
      Gd2[2*j] += gr; Gd2[2*j+1] += gi;
